/// The Unix time this image was built at.
///
/// A Pico has no RTC on the chip, so a software clock has to start somewhere. The extension writes
/// the build's own time into `.cargo/config.toml` before every build, which makes "set when it was
/// flashed" true to the second the compiler started -- and on a W board the network corrects it.
#[allow(dead_code)]
const BUILD_EPOCH: i64 = match option_env!("RUSTY_EPOCH") {
    Some(text) => match parse_i64(text) {
        Some(value) => value,
        None => 0,
    },
    None => 0,
};

/// Minutes to add to UTC to get the time on the glass. Written by the project wizard; edit it when the
/// clocks change, because a `no_std` image has no timezone database.
#[allow(dead_code)]
pub const UTC_OFFSET_MINUTES: i64 = 0;

/// Parses a signed decimal number, or nothing: the value is a build-time string, so a typo has to read
/// as "no time yet" rather than as a panic.
#[allow(dead_code)]
const fn parse_i64(text: &str) -> Option<i64> {
    let bytes = text.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let (negative, digits) = match bytes[0] {
        b'-' => (true, 1),
        b'+' => (false, 1),
        _ => (false, 0),
    };
    if digits >= bytes.len() {
        return None;
    }
    let mut value: i64 = 0;
    let mut index = digits;
    while index < bytes.len() {
        let byte = bytes[index];
        if byte < b'0' || byte > b'9' {
            return None;
        }
        value = value * 10 + (byte - b'0') as i64;
        index += 1;
    }
    Some(if negative { -value } else { value })
}

/// The wall clock the firmware starts from: the build's own time, in local time.
#[allow(dead_code)]
pub fn boot_time() -> (u8, u8, u8) {
    let seconds = BUILD_EPOCH + UTC_OFFSET_MINUTES * 60;
    let of_day = seconds.rem_euclid(86_400);
    (
        (of_day / 3_600) as u8,
        ((of_day % 3_600) / 60) as u8,
        (of_day % 60) as u8,
    )
}

